use std::cmp::Ordering;

use rpm_version::compare_rpm_versions;

#[test]
fn test_rpm_version_compare() {
    for (a, x, b) in TEST_CASES {
        match compare_rpm_versions(a, b) {
            Some(actual) => {
                assert_eq!(
                    actual, *x,
                    "Testing failed: expected {} {:?} {}, but got {:?}",
                    a, x, b, actual
                );
                println!("✅: {} {:?} {}", a, x, b);
            }
            None => {
                panic!("Failed to compare {} and {}", a, b,)
            }
        }
    }
}

